import itertools

def get_digits(n):
    return [int(d) for d in str(n)]

def is_distinct_nonzero(digits):
    if not digits:
        return False
    return len(set(digits)) == len(digits) and all(d != 0 for d in digits)

# Memoization for good numbers check
good_cache = {}

def is_good(m):
    if m in good_cache:
        return good_cache[m]

    s_m = str(m)
    k = len(s_m)
    digits = get_digits(m)

    # 1. Base Case: Single-digit numbers
    if k == 1:
        result = True
        good_cache[m] = result
        return result

    # 2. Recursive Step: Check removal of every digit d_j
    for j in range(k):
        # Form m' by removing the j-th digit
        m_prime_str = s_m[:j] + s_m[j+1:]

        if not m_prime_str:
            continue # Should not happen for k >= 2

        m_prime = int(m_prime_str)

        # Check if m' is a valid candidate (must use distinct, nonzero digits)
        prime_digits = get_digits(m_prime)
        if not is_distinct_nonzero(prime_digits):
            continue

        # Check Divisibility Condition: m' | m
        if m % m_prime == 0:
            # Check Recursion Condition: m' must be a good number
            if is_good(m_prime):
                # Found one way for m to be good
                good_cache[m] = True
                return True

    # If no removal satisfies the conditions
    good_cache[m] = False
    return False

# Initializing known good numbers from the problem definition (1-9)
for i in range(1, 10):
    is_good(i)

# Search for the largest good number by iterating downwards for k=3 (987 -> 125)
print("Starting search for largest k=3 good number...")
largest_good = 0

# Iterate d2 from 9 down to 1
for d2 in range(9, 0, -1):
    # Iterate d1 from 9 down to 1 (d1 != d2)
    for d1 in range(9, 0, -1):
        if d1 == d2:
            continue
        # Iterate d0 from 9 down to 1 (d0 != d2, d0 != d1)
        for d0 in range(9, 0, -1):
            if d0 == d2 or d0 == d1:
                continue

            m = 100 * d2 + 10 * d1 + d0

            # Check if m is good
            if is_good(m):
                print(f"Found good number: {m}")
                if m > largest_good:
                    largest_good = m

print(f"Search finished. Largest k=3 good number found: {largest_good}")
